      r.poly([[cx - 1, cy + 2], [cx + 5.5, cy + 2.5], [cx + 5, cy + 8.5], [cx + 1, cy + 10], [cx - 2, cy + 6]], PAL.hair, { v: 0.45 });
      eye(r, cx + 3.4, cy + 0.5, { white: "#f0e0d0", red: true });
