    const nz = n.z + n.vz / 60;
    if (ok(nx, nz)) {
      n.x = nx;
      n.z = nz;
    } else if (ok(nx, n.z)) {
      n.x = nx;
      n.vz = 0;
    } else if (ok(n.x, nz)) {
      n.z = nz;
      n.vx = 0;
      moved = !wx;
    } else {
      n.vx = n.vz = 0;
      moved = false;
    }
    const sp = Math.hypot(n.vx, n.vz);
