    if (!h) {
      b.spare = false;
      this.passed = b;
      return false;
    }
    const W = this.world;
    this.boss = b;
    this.hero = h;
    this.blowOf = this.blow(h);
    this.count++;
    b.sentenced = true;
    b.invincible = true;
    b.entering = false;
    b.unbounded = false;
    b.controller = new Controller();
