  skid: 18,
  // then the skid to a stop
  from: -230,
  to: 150,
  // where the heroes run from and stop
  run: 9,
  // the commanders' run off (px a frame)
  gone: 1420,
  // ...until they're this far along, out of sight
  charge: 30,
