// src/net/Version.js
function text(v, depth = 0) {
  if (typeof v === "function") return String(v);
  if (v && typeof v === "object" && depth < 4) {
    return Object.keys(v).sort().map((k) => `${k}:${text(v[k], depth + 1)}`).join("|");
  }
  return JSON.stringify(v) ?? "";
}
var cached = null;
function simVersion() {
  if (cached) return cached;
  const src2 = [
    CHARACTERS,
    ENEMIES,
    WAVES,
    STAGE,
    STAGES,
    PICKUPS,
    PROPS,
    ACTIONS,
    World,
    Stage,
    CombatSystem,
    Fighter,
    EnemyBrain,
    createEnemy,
    Projectile,
    Barriers,
    Mines,
    { ...fighterStates_exports },
    { ...Mage_exports },
    { ...Rogue_exports },
    { ...Finisher_exports },
    { ...Session_exports }
  ].map((v) => text(v)).join("\n");
  let h = 2166136261;
  for (let i = 0; i < src2.length; i++) {
    h ^= src2.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  cached = (h >>> 0).toString(36).toUpperCase().padStart(7, "0").slice(-5);
  return cached;
}

