var PROGRESS = {
  key: "bloodaxe.progress.v1",
  levelStep: 300,
  // blood a level (a grunt is worth ~12, a brute ~25, an elite ~80)
  startPoints: 2,
  // enough for one first-tier skill at the first shrine
  bloodPer: 1 / 6
  // blood for a kill = the man's max health x this
};
var fresh = () => ({ v: 1, blood: 0, bonus: PROGRESS.startPoints, picks: {}, claimed: {}, campaign: freshCampaign(), trophies: freshTrophies() });
