      this.tweens.killTweensOf(h2.ground);
      for (const gnd of h2.ground) {
        gnd.setDepth(on ? 4.5 : 1.4);
        this.tweens.add({ targets: gnd, alpha: on ? 0.7 : 0.45, duration: instant ? 0 : 300 });
      }
      this.tweens.add({ targets: h2.color, alpha: on ? 1 : 0, duration: instant ? 0 : on ? 420 : 220 });
      this.tweens.add({ targets: h2.rim, alpha: on ? 0 : 0.55, duration: instant ? 0 : 300 });
      for (const p of h2.parts) p.setDepth(on ? 5 : 2);
