    this.beam.setAlpha(0);
    this.tweens.add({ targets: this.beam, alpha: 1, duration: instant ? 0 : 320, ease: "Sine.easeOut" });
    this.pool.setPosition(h.x + DISC.dx, h.y + DISC.dy).setDisplaySize(DISC.w, DISC.h).setDepth(3).setAlpha(0);
