    const ux = A.x * d;
    const uy = A.y;
    const px = -uy;
    const py = ux;
    const w = A.w * k * sc2;
    const from = A.from * k * sc2;
    const edge = Math.sqrt(Math.max(0, r * r - w * w));
    const a0 = Math.atan2(uy, ux);
    const half = Math.asin(Math.min(1, w / r));
