      g.fillStyle(C3.ironDk, 1).fillRect(ex - 18, ey + 32, 36, 8);
      g.fillStyle(C3.rivet, 1).fillCircle(px, py, 6);
      g.fillStyle(C3.ironDk, 1).fillRect(Math.min(X(56), X(70 + drumOut)), dy - 6, Math.abs(14 + drumOut), 12);
      g.fillStyle(iron, 1).fillCircle(dx, dy, 36);
