      g.fillStyle(C3.spike, 1);
      for (let k = 0; k < 8; k++) {
        const a = drumSpin + k * Math.PI / 4;
        const c = Math.cos(a);
        const s = Math.sin(a);
        g.fillTriangle(dx + c * 33 - s * 6, dy + s * 33 + c * 6, dx + c * 33 + s * 6, dy + s * 33 - c * 6, dx + c * 50, dy + s * 50);
      }
